import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import axiosInstance from '../axiosConfig';

const TaskForm = ({ tasks, setTasks, editingTask, setEditingTask }) => {
  const { user } = useAuth();
  const [formData, setFormData] = useState({ title: '', description: '', deadline: '' });

  useEffect(() => {
    if (editingTask) {
      setFormData({
        title: editingTask.title,
        description: editingTask.description,
        deadline: editingTask.deadline,
      });
    } else {
      setFormData({ title: '', description: '', deadline: '' });
    }
  }, [editingTask]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingTask) {
        const response = await axiosInstance.put(`/api/tasks/${editingTask._id}`, formData, {
          headers: { Authorization: `Bearer ${user.token}` },
        });
        setTasks(tasks.map((task) => (task._id === response.data._id ? response.data : task)));
      } else {
        const response = await axiosInstance.post('/api/tasks', formData, {
          headers: { Authorization: `Bearer ${user.token}` },
        });
        setTasks([...tasks, response.data]);
      }
      setEditingTask(null);
      setFormData({ title: '', description: '', deadline: '' });
    } catch (error) {
      alert('Failed to save task.');
    }
  };

  return (
  <div className="bg-white p-6 shadow-md rounded mb-6">
    <h1 className="text-2xl font-bold mb-4">Product #1</h1>

    <div className="flex gap-6 items-start">

      <img
        src="/images/product1.jpg"
        alt="Product 1"
        className="w-64 h-64 object-cover rounded"
      />

      <div className="flex-1">
        <h2 className="text-xl font-bold mb-2">
          Handmade Craft Product
        </h2>

        <p className="mb-4">
          Beautiful handmade product.
        </p>

        <h2 className="text-2xl font-bold mb-4">
          $29.99
        </h2>

        <button
          className="w-full bg-blue-600 text-white p-3 rounded"
        >
          Add to Cart
        </button>
      </div>

    </div>
  </div>
);
};

export default TaskForm;
